export type BrandMarkProps = SVGProps<SVGSVGElement> & { brand?: boolean };

/**
 * The props for a one-colour mark: `currentColor` unless the caller asks for the
 * brand, and then the brand's colour through `color`, so every `currentColor`
 * fill in the mark follows it. A brand whose own colour is black (or as good as)
 * passes none and keeps following the surface, which is what its own black and
 * white variants do; one that would all but vanish on either theme does too.
 */
function brandMark(
    props: SVGProps<SVGSVGElement>,
    brand: boolean | undefined,
    color: string | undefined
): SVGProps<SVGSVGElement> {
    if (!brand || !color) return mark(props);
    return mark({ ...props, style: { ...props.style, color } as CSSProperties });
}

